class Counter:
    total_count = 0  # class attribute

    def __init__(self, name):
        self.name = name       # instance attribute
        self.id = Counter.total_count
        Counter.total_count += 1

    # Instance method -- needs self
    def describe(self):
        return f"Counter {self.id}: {self.name}"

    # Class method -- needs cls
    @classmethod
    def get_total(cls):
        return cls.total_count

    # Static method -- neither self nor cls
    @staticmethod
    def is_valid_name(name):
        return len(name) > 0

c1 = Counter("A")
c2 = Counter("B")
print(c1.describe())          # Counter 0: A
print(Counter.get_total())   # 2
print(Counter.is_valid_name("X"))  # True

