class Book:
    def __init__(self, title, pages):
        self.title = title
        self.pages = pages

    def __str__(self):
        # What print() and str() show
        return f"'{self.title}' ({self.pages} pages)"

    def __repr__(self):
        # What the REPL shows (developer-focused)
        return f"Book('{self.title}', {self.pages})"

    def __len__(self):
        # What len() returns
        return self.pages

    def __eq__(self, other):
        # What == does
        if isinstance(other, Book):
            return self.title == other.title
        return False

    def __add__(self, other):
        # What + does
        if isinstance(other, Book):
            return Book(f"{self.title} & {other.title}",
                        self.pages + other.pages)

b1 = Book("Python 101", 200)
b2 = Book("Advanced Python", 300)

print(b1)            # 'Python 101' (200 pages)
print(repr(b1))      # Book('Python 101', 200)
print(len(b1))       # 200
print(b1 == b2)      # False
combined = b1 + b2
print(combined)      # 'Python 101 & Advanced Python' (500 pages)

# break -- exit loop entirely
for i in range(10):
    if i == 5:
        break
    print(i)  # prints 0, 1, 2, 3, 4

# continue -- skip to next iteration
for i in range(5):
    if i == 2:
        continue
    print(i)  # prints 0, 1, 3, 4 (skips 2)

